#!/usr/bin/env bash
# MUT-4 (r101) — capture real-Godot receipts for the pristine C3 fixture and its forgeries.
# Scratch project: /tmp/r101-mut04/proj2 (generated by mut04_ytrans_gen.py).
set -u
OUT=/tmp/r101-mut04/out2
PROJ=/tmp/r101-mut04/proj2
mkdir -p "$OUT" /tmp/r101-mut04/xdg-data
export XDG_DATA_HOME=/tmp/r101-mut04/xdg-data
: > "$OUT/run_log.txt"

run() {
  local name=$1 script=$2; shift 2
  local t0 t1 rc
  t0=$(date +%s)
  timeout 120 godot --headless --path "$PROJ" --script "res://$script" -- "$@" \
    > "$OUT/$name.stdout" 2> "$OUT/$name.stderr"
  rc=$?
  t1=$(date +%s)
  echo "$rc" > "$OUT/$name.rc"
  printf '%s rc=%s secs=%ss cmd=godot --headless --path %s --script res://%s -- %s\n' \
    "$name" "$rc" "$((t1 - t0))" "$PROJ" "$script" "$*" >> "$OUT/run_log.txt"
}

# pristine baseline, all four arms
run base_ytrans1000 r101_ytrans.gd --arm=ytrans --offy=1000
run base_ytrans0    r101_ytrans.gd --arm=ytrans --offy=0
run base_ysep       r101_ytrans.gd --arm=ysep
run base_ycop       r101_ytrans.gd --arm=ycop
run base_census     r101_ytrans.gd --arm=census

# forgeries
run mut_noop_full        ytrans_mut_noop_full.gd      --arm=ytrans --offy=1000
run mut_omitevid         ytrans_mut_omitevid.gd       --arm=ytrans --offy=1000
run mut_omitevid_noop    ytrans_mut_omitevid_noop.gd  --arm=ytrans --offy=1000
run mut_swapkeys         ytrans_mut_swapkeys.gd       --arm=ytrans --offy=1000

cat "$OUT/run_log.txt"
